/* Homepage image assets as data URIs, imported ONLY by the client
   component (app/components/HomeClient.tsx), which assigns them to the
   matching <img data-asset="..."> elements on mount. They deliberately
   live in the client JS bundle and not in app/home-markup.ts: when they
   were interpolated into the server rendered markup string, every byte
   shipped twice in the HTML document (rendered markup plus the RSC
   flight payload) and the homepage document was 3.5MB. In the bundle
   each asset ships once, in a cacheable file. Each image is encoded at
   roughly twice its displayed size and no larger. There is no font
   asset here: the custom display font was removed entirely at
   Calista's request (it never rendered on her devices), and display
   headings use the Helvetica Neue stack from home.css. */

export const CE_LOGO = "data:image/webp;base64,";

